import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ContractService } from '@services/contract.service';
import { ConfigService } from '@services/config.service';
import { ToastService } from '@services/toast.service';
import { ConfirmModalService } from '@services/confirm-modal.service';

import { TransactionInterceptorService } from '@services/transaction-interceptor.service';
import { IconComponent } from '@components/ui/icon/icon.component';
import { ContactInputComponent } from '@components/ui/contact-input/contact-input.component';
import { getTokens } from '@core/token-config';
import { ethers } from 'ethers';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { LoggerService } from "@services/logger.service";
import { NetworkService } from '@services/network.service';

interface TokenOption {
    name: string;
    address: string;
    decimals?: number; // preloaded to avoid on-chain call failures
}

@Component({
    selector: 'app-transfer',
    standalone: true,
    imports: [CommonModule, FormsModule, IconComponent, ContactInputComponent, TranslateModule],
    templateUrl: './transfer.component.html'
})
export class TransferComponent implements OnInit, OnDestroy {
    fromAddress = ''; // Address to transfer from (default: connected wallet)
    transferType: 'ETH' | 'TOKEN' = 'ETH';
    transferRecipient = '';
    transferAmount = '';
    selectedToken = '';
    customTokenAddress = '';
    tokens: TokenOption[] = [];
    transferring = false;
    ethBalance = '';
    tokenBalance = '';
    loadingBalance = false;

    constructor(
        private contractService: ContractService,
        public configService: ConfigService,
        private toastService: ToastService,
        private confirmModalService: ConfirmModalService,
        private txInterceptor: TransactionInterceptorService,
        private networkService: NetworkService,
        private translate: TranslateService, private logger: LoggerService
    ) { }

    ngOnInit() {
        this.logger.debug('[TransferComponent] initialized');
        // Set default from address to connected wallet
        this.setDefaultFromAddress();

        this.loadTokens();
        this.loadETHBalance();
    }

    async setDefaultFromAddress() {
        try {
            const { ethereum } = window as any;
            if (ethereum) {
                const accounts = await ethereum.request({ method: 'eth_accounts' });
                if (accounts && accounts.length > 0) {
                    this.fromAddress = accounts[0];
                }
            }
        } catch (e) {
            this.logger.error('Failed to get default address:', e);
        }
    }

    async loadETHBalance() {
        try {
            this.loadingBalance = true;

            let addressToCheck = this.fromAddress;
            if (!addressToCheck) {
                const { ethereum } = window as any;
                if (ethereum) {
                    const accounts = await ethereum.request({ method: 'eth_accounts' });
                    addressToCheck = accounts ? accounts[0] : null;
                }
            }

            if (!addressToCheck) {
                throw new Error('No address specified');
            }

            const provider = this.configService.rpcUrl 
                ? new ethers.JsonRpcProvider(this.configService.rpcUrl) 
                : new ethers.BrowserProvider((window as any).ethereum);
            const network = await provider.getNetwork();
            this.logger.debug('🔍 [ETH Balance] Network info:', {
                chainId: network.chainId.toString(),
                name: network.name,
                account: addressToCheck,
                rpcUrl: this.configService.rpcUrl
            });

            const balance = await provider.getBalance(addressToCheck);
            this.logger.debug('🔍 [ETH Balance] Raw balance:', balance.toString());

            this.ethBalance = ethers.formatEther(balance);
            this.logger.debug('🔍 [ETH Balance] Formatted:', this.ethBalance, 'ETH');
        } catch (e: any) {
            this.logger.error('❌ [ETH Balance] Failed to load ETH balance', e);
            this.ethBalance = '0';
        } finally {
            this.loadingBalance = false;
        }
    }

    get effectiveTokenAddress(): string {
        return this.selectedToken === 'custom' ? this.customTokenAddress : this.selectedToken;
    }

    async loadTokenBalance() {
        const tokenAddress = this.effectiveTokenAddress;
        if (!tokenAddress || (this.selectedToken === 'custom' && !ethers.isAddress(tokenAddress))) {
            this.tokenBalance = '';
            return;
        }

        try {
            this.loadingBalance = true;

            let addressToCheck = this.fromAddress;
            if (!addressToCheck) {
                const { ethereum } = window as any;
                if (ethereum) {
                    const accounts = await ethereum.request({ method: 'eth_accounts' });
                    addressToCheck = accounts ? accounts[0] : null;
                }
            }

            if (!addressToCheck) {
                throw new Error('No address specified');
            }

            const provider = this.configService.rpcUrl 
                ? new ethers.JsonRpcProvider(this.configService.rpcUrl) 
                : new ethers.BrowserProvider((window as any).ethereum);

            const tokenConfig = this.tokens.find(t => t.address === tokenAddress);

            const tokenAbi = [
                'function decimals() external view returns (uint8)',
                'function balanceOf(address) external view returns (uint256)',
                'function symbol() external view returns (string)',
                'function name() external view returns (string)'
            ];
            
            // Use provider instead of signer for view operations to avoid triggering eth_accounts in Ethers V6
            const token = new ethers.Contract(tokenAddress, tokenAbi, provider);

            // Use preloaded decimals if available, otherwise try on-chain call
            // with fallback to 18 to handle contracts that return 0x (wrong network, non-standard)
            const decimals = tokenConfig?.decimals !== undefined
                ? tokenConfig.decimals
                : await this.safeGetDecimals(token);

            let balance: bigint;
            try {
                balance = await token['balanceOf'](addressToCheck);
            } catch {
                balance = BigInt(0);
            }

            this.tokenBalance = ethers.formatUnits(balance, decimals);
        } catch (e: any) {
            this.logger.error('Failed to load token balance', e);
            this.tokenBalance = '0';
        } finally {
            this.loadingBalance = false;
        }
    }

    /**
     * Safely fetch decimals() from a token contract.
     * Falls back to 18 if the call fails or returns empty data (e.g. wrong network,
     * non-standard token, or address has no contract code).
     */
    private async safeGetDecimals(token: ethers.Contract): Promise<number> {
        try {
            return Number(await token['decimals']());
        } catch {
            this.logger.warn('⚠️ decimals() call failed, falling back to 18 decimals');
            return 18;
        }
    }

    /**
     * Handle from address change - reload balances
     */
    onFromAddressChange() {
        if (this.transferType === 'ETH') {
            this.loadETHBalance();
        } else {
            this.loadTokenBalance();
        }
    }

    /**
     * Set from address to currently connected wallet
     */
    async setFromAddressToMe() {
        try {
            const { ethereum } = window as any;
            if (ethereum) {
                const accounts = await ethereum.request({ method: 'eth_accounts' });
                if (accounts && accounts.length > 0) {
                    this.fromAddress = accounts[0];
                    // Reload balance for the new address
                    this.onFromAddressChange();
                }
            }
        } catch (e) {
            this.logger.error('Failed to set address to me:', e);
        }
    }

    loadTokens() {
        const mode = this.configService.mode;
        const allTokens = getTokens(mode);

        // Map TokenConfig to TokenOption format, preserving preloaded decimals
        this.tokens = allTokens.map(t => ({
            name: `${t.symbol} - ${t.name}`,
            address: t.address,
            decimals: t.decimals
        }));

        this.logger.debug(`Loaded ${this.tokens.length} tokens for ${mode} mode`);
    }

    getExplorerName(): string {
        try {
            const url = this.networkService.getNetworkConfig().explorerUrl || '';
            const lowerUrl = url.toLowerCase();
            if (lowerUrl.includes('bscscan')) return 'BscScan';
            if (lowerUrl.includes('polygonscan')) return 'PolygonScan';
            if (lowerUrl.includes('snowtrace')) return 'Snowtrace';
            if (lowerUrl.includes('arbiscan')) return 'Arbiscan';
            if (lowerUrl.includes('optimistic')) return 'Optimism Explorer';
        } catch (e) {
            this.logger.error('Failed to get explorer name', e);
        }
        return 'Etherscan';
    }

    /**
     * Get Etherscan link for token contract
     */
    getEtherscanLink(address: string): string {
        try {
            const baseUrl = this.networkService.getNetworkConfig().explorerUrl;
            if (baseUrl) {
                const normalizedBase = baseUrl.endsWith('/') ? baseUrl.slice(0, -1) : baseUrl;
                return `${normalizedBase}/token/${address}`;
            }
        } catch (e) {
            this.logger.error('Failed to get explorer url', e);
        }
        // Fallback
        const isMainnet = this.configService.chainId === 1;
        const baseUrl = isMainnet ? 'https://etherscan.io' : 'https://sepolia.etherscan.io';
        return `${baseUrl}/token/${address}`;
    }

    async onTokenSelectionChange() {
        if (this.selectedToken !== 'custom') {
            await this.loadTokenBalance();
        } else {
            this.tokenBalance = '';
        }
    }

    async onCustomTokenChange() {
        if (ethers.isAddress(this.customTokenAddress)) {
            await this.loadTokenBalance();
        } else {
            this.tokenBalance = '';
        }
    }

    setAmountPercentage(percentage: number) {
        try {
            if (this.transferType === 'ETH') {
                if (!this.ethBalance || this.ethBalance === '0') return;
                const balanceWei = ethers.parseEther(this.ethBalance);
                const amountWei = (balanceWei * BigInt(percentage)) / BigInt(100);
                this.transferAmount = ethers.formatEther(amountWei);
            } else {
                const tokenAddress = this.effectiveTokenAddress;
                if (!this.tokenBalance || this.tokenBalance === '0' || !tokenAddress) return;
                const tokenConfig = this.tokens.find(t => t.address === tokenAddress);
                const decimals = tokenConfig?.decimals !== undefined ? tokenConfig.decimals : 18;

                const balanceUnits = ethers.parseUnits(this.tokenBalance, decimals);
                const amountUnits = (balanceUnits * BigInt(percentage)) / BigInt(100);
                this.transferAmount = ethers.formatUnits(amountUnits, decimals);
            }
        } catch (e) {
            this.logger.error('Failed to calculate percentage amount', e);
        }
    }

    useMaxETH() {
        this.transferAmount = this.ethBalance;
    }

    useMaxToken() {
        this.transferAmount = this.tokenBalance;
    }

    async transferETH() {
        if (!this.transferRecipient || !this.transferAmount) {
            this.toastService.warning(this.translate.instant('TRANSFER.ERRORS.FILL_ALL'));
            return;
        }

        if (!ethers.isAddress(this.transferRecipient)) {
            this.toastService.error(this.translate.instant('TRANSFER.ERRORS.INVALID_ADDRESS'));
            return;
        }

        if (!await this.confirmModalService.confirm(this.translate.instant('TRANSFER.CONFIRM_TRANSFER_ETH', { amount: this.transferAmount, recipient: this.transferRecipient }))) {
            return;
        }

        try {
            this.transferring = true;
            const locker = this.contractService.getLockerContract();
            const signer = locker.runner as any;

            // Use transaction interceptor for air-gapped support
            const receipt = await this.txInterceptor.executeTransaction({
                to: this.transferRecipient,
                value: ethers.parseEther(this.transferAmount),
                metadata: {
                    operation: 'Transfer ETH',
                    args: {
                        recipient: this.transferRecipient,
                        amount: `${this.transferAmount} ETH`
                    }
                }
            }, signer);

            // If receipt is null, user chose offline mode
            if (receipt) {
                if (typeof receipt.wait === 'function') {
                    await receipt.wait();
                }
                this.toastService.success(this.translate.instant('TRANSFER.SUCCESS.ETH_SENT', { amount: this.transferAmount, recipient: this.transferRecipient }));
                this.transferRecipient = '';
                this.transferAmount = '';
                await this.loadETHBalance();
            } else {
                // Offline mode - transaction will be broadcasted later
                this.toastService.info(this.translate.instant('TRANSFER.INFO.OFFLINE_SENT'));
            }
        } catch (e: any) {
            this.logger.error('Failed to transfer ETH', e);
            this.toastService.error(this.translate.instant('TRANSFER.ERRORS.TRANSFER_FAILED') + ': ' + e.message);
        } finally {
            this.transferring = false;
        }
    }

    async transferToken() {
        const tokenAddress = this.effectiveTokenAddress;

        if (!tokenAddress || !this.transferRecipient || !this.transferAmount) {
            this.toastService.warning(this.translate.instant('TRANSFER.ERRORS.FILL_ALL'));
            return;
        }

        if (!ethers.isAddress(this.transferRecipient)) {
            this.toastService.error(this.translate.instant('TRANSFER.ERRORS.INVALID_ADDRESS'));
            return;
        }

        let tokenName = 'Custom Token';
        let decimals = 18;

        const locker = this.contractService.getLockerContract();
        const signer = locker.runner as ethers.Signer;

        const tokenAbi = [
            'function decimals() external view returns (uint8)',
            'function symbol() external view returns (string)',
            'function name() external view returns (string)',
            'function transfer(address to, uint256 amount) external returns (bool)'
        ];
        const token = new ethers.Contract(tokenAddress, tokenAbi, signer);

        const tokenInfo = this.tokens.find(t => t.address === tokenAddress);
        if (tokenInfo) {
            tokenName = tokenInfo.name;
            decimals = tokenInfo.decimals !== undefined ? tokenInfo.decimals : await this.safeGetDecimals(token);
        } else {
            // Fetch name for custom token
            try {
                tokenName = await token['symbol']();
            } catch {
                tokenName = 'Custom Token';
            }
            decimals = await this.safeGetDecimals(token);
        }

        if (!await this.confirmModalService.confirm(this.translate.instant('TRANSFER.CONFIRM_TRANSFER_TOKEN', { amount: this.transferAmount, token: tokenName, recipient: this.transferRecipient }))) {
            return;
        }

        try {
            this.transferring = true;

            const amount = ethers.parseUnits(this.transferAmount, decimals);

            // Encode transfer function call
            const data = token.interface.encodeFunctionData('transfer', [this.transferRecipient, amount]);

            // Use transaction interceptor for air-gapped support
            const receipt = await this.txInterceptor.executeTransaction({
                to: tokenAddress,
                data: data,
                metadata: {
                    operation: 'Transfer Token',
                    contract: tokenName,
                    function: 'transfer',
                    args: {
                        to: this.transferRecipient,
                        amount: `${this.transferAmount} ${tokenName}`
                    }
                }
            }, signer);

            // If receipt is null, user chose offline mode
            if (receipt) {
                if (typeof receipt.wait === 'function') {
                    await receipt.wait();
                }
                this.toastService.success(this.translate.instant('TRANSFER.SUCCESS.TOKEN_SENT', { amount: this.transferAmount, token: tokenName, recipient: this.transferRecipient }));
                this.transferRecipient = '';
                this.transferAmount = '';
                await this.loadTokenBalance();
            } else {
                // Offline mode - transaction will be broadcasted later
                this.toastService.info(this.translate.instant('TRANSFER.INFO.OFFLINE_SENT'));
            }
        } catch (e: any) {
            this.logger.error('Failed to transfer token', e);
            this.toastService.error(this.translate.instant('TRANSFER.ERRORS.TRANSFER_FAILED') + ': ' + e.message);
        } finally {
            this.transferring = false;
        }
    }

    ngOnDestroy(): void {
        this.logger.debug('[TransferComponent] destroyed');
    }
}
