import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import {
    NetworkConfig,
    NetworkType,
    ContractAddresses,
    NetworkEnvironment,
    CustomLockerConfig
} from '../config/network-config.interface';
import { ETHEREUM_MAINNET, ETHEREUM_HARDHAT } from '../config/networks/ethereum.config';
import { BSC_MAINNET, BSC_TESTNET } from '../config/networks/bsc.config';
import { ETHEREUM_MAINNET_CONTRACTS } from '../config/networks/ethereum-mainnet.config';

// Import testnet config (auto-generated)
import {
    ETHEREUM_TESTNET_CONTRACTS,
    ETHEREUM_TESTNET_TOKENS,
    ETHEREUM_TESTNET_PAIRS
} from '../config/networks/ethereum-testnet.config';

const STORAGE_KEY_NETWORK = 'ag_selected_network';
const STORAGE_KEY_CUSTOM_LOCKER = 'ag_custom_locker';

@Injectable({
    providedIn: 'root'
})
export class NetworkService {
    private currentNetworkSubject = new BehaviorSubject<NetworkType>('eth-testnet');
    private contractAddressesSubject = new BehaviorSubject<ContractAddresses | null>(null);
    private customLockerSubject = new BehaviorSubject<CustomLockerConfig | null>(null);

    public currentNetwork$: Observable<NetworkType> = this.currentNetworkSubject.asObservable();
    public contractAddresses$: Observable<ContractAddresses | null> = this.contractAddressesSubject.asObservable();
    public customLocker$: Observable<CustomLockerConfig | null> = this.customLockerSubject.asObservable();

    constructor() {
        this.loadFromStorage();
    }

    /**
     * Get current network type
     */
    getCurrentNetwork(): NetworkType {
        return this.currentNetworkSubject.value;
    }

    /**
     * Get current network configuration
     */
    getNetworkConfig(): NetworkConfig {
        const networkType = this.getCurrentNetwork();
        return this.getNetworkConfigByType(networkType);
    }

    /**
     * Get network config by type
     */
    getNetworkConfigByType(networkType: NetworkType): NetworkConfig {
        switch (networkType) {
            case 'eth-mainnet':
                return ETHEREUM_MAINNET;
            case 'eth-testnet':
                return ETHEREUM_HARDHAT;
            case 'bsc-mainnet':
                return BSC_MAINNET;
            case 'bsc-testnet':
                return BSC_TESTNET;
            default:
                return ETHEREUM_HARDHAT;
        }
    }

    /**
     * Get current contract addresses
     */
    getContractAddresses(): ContractAddresses | null {
        return this.contractAddressesSubject.value;
    }

    /**
     * Get default contract addresses for a network
     */
    getDefaultContracts(networkType: NetworkType): ContractAddresses {
        switch (networkType) {
            case 'eth-mainnet':
                return ETHEREUM_MAINNET_CONTRACTS;
            case 'eth-testnet':
                return ETHEREUM_TESTNET_CONTRACTS;
            case 'bsc-mainnet':
            case 'bsc-testnet':
                // TODO: Add BSC contract addresses when deployed
                return {
                    locker: '0x0000000000000000000000000000000000000000'
                };
            default:
                return ETHEREUM_TESTNET_CONTRACTS;
        }
    }

    /**
     * Switch to a different network
     */
    switchNetwork(networkType: NetworkType): void {
        console.log(`🔄 Switching network to: ${networkType}`);

        this.currentNetworkSubject.next(networkType);

        // Check if there's a custom locker for this network
        const customLocker = this.customLockerSubject.value;

        if (customLocker && customLocker.network === networkType) {
            // Use custom locker contracts
            this.contractAddressesSubject.next(customLocker.contracts);
        } else {
            // Use default contracts for this network
            const defaultContracts = this.getDefaultContracts(networkType);
            this.contractAddressesSubject.next(defaultContracts);
        }

        this.saveToStorage();
    }

    /**
     * Set custom locker address and load its contracts
     */
    async setCustomLocker(lockerAddress: string, contracts: ContractAddresses): Promise<void> {
        const networkType = this.getCurrentNetwork();

        const customConfig: CustomLockerConfig = {
            network: networkType,
            lockerAddress,
            contracts,
            timestamp: Date.now()
        };

        this.customLockerSubject.next(customConfig);
        this.contractAddressesSubject.next(contracts);
        this.saveToStorage();

        console.log(`✅ Custom Locker set: ${lockerAddress}`);
    }

    /**
     * Reset to default configuration for current network
     */
    resetToDefault(): void {
        console.log('🔄 Resetting to default configuration...');

        const networkType = this.getCurrentNetwork();
        const defaultContracts = this.getDefaultContracts(networkType);

        this.customLockerSubject.next(null);
        this.contractAddressesSubject.next(defaultContracts);
        this.saveToStorage();

        console.log('✅ Reset to default configuration');
    }

    /**
     * Get complete network environment (config + contracts + tokens + pairs)
     */
    getNetworkEnvironment(): NetworkEnvironment {
        const network = this.getNetworkConfig();
        const contracts = this.getContractAddresses() || this.getDefaultContracts(this.getCurrentNetwork());

        // Try to get tokens and pairs for testnet
        let tokens, pairs;
        if (this.getCurrentNetwork() === 'eth-testnet') {
            tokens = ETHEREUM_TESTNET_TOKENS;
            pairs = ETHEREUM_TESTNET_PAIRS;
        }

        return {
            network,
            contracts,
            tokens,
            pairs
        };
    }

    /**
     * Check if using custom locker
     */
    isUsingCustomLocker(): boolean {
        return this.customLockerSubject.value !== null;
    }

    /**
     * Load configuration from localStorage
     */
    private loadFromStorage(): void {
        try {
            // Load selected network
            const storedNetwork = localStorage.getItem(STORAGE_KEY_NETWORK);
            if (storedNetwork && this.isValidNetworkType(storedNetwork)) {
                this.currentNetworkSubject.next(storedNetwork as NetworkType);
            }

            // Load custom locker if exists
            const storedCustomLocker = localStorage.getItem(STORAGE_KEY_CUSTOM_LOCKER);
            if (storedCustomLocker) {
                const customConfig: CustomLockerConfig = JSON.parse(storedCustomLocker);

                // Only load if it's for the current network
                if (customConfig.network === this.currentNetworkSubject.value) {
                    this.customLockerSubject.next(customConfig);
                    this.contractAddressesSubject.next(customConfig.contracts);
                    return;
                }
            }

            // Load default contracts if no custom locker
            const defaultContracts = this.getDefaultContracts(this.currentNetworkSubject.value);
            this.contractAddressesSubject.next(defaultContracts);

        } catch (error) {
            console.error('❌ Error loading config from storage:', error);
            // Fallback to defaults
            const defaultContracts = this.getDefaultContracts('eth-testnet');
            this.contractAddressesSubject.next(defaultContracts);
        }
    }

    /**
     * Save configuration to localStorage
     */
    private saveToStorage(): void {
        try {
            localStorage.setItem(STORAGE_KEY_NETWORK, this.currentNetworkSubject.value);

            const customLocker = this.customLockerSubject.value;
            if (customLocker) {
                localStorage.setItem(STORAGE_KEY_CUSTOM_LOCKER, JSON.stringify(customLocker));
            } else {
                localStorage.removeItem(STORAGE_KEY_CUSTOM_LOCKER);
            }
        } catch (error) {
            console.error('❌ Error saving config to storage:', error);
        }
    }

    /**
     * Validate network type
     */
    private isValidNetworkType(value: string): boolean {
        return ['eth-mainnet', 'eth-testnet', 'bsc-mainnet', 'bsc-testnet'].includes(value);
    }

    /**
     * Get all available networks
     */
    getAvailableNetworks(): Array<{ type: NetworkType; config: NetworkConfig }> {
        return [
            { type: 'eth-mainnet', config: this.getNetworkConfigByType('eth-mainnet') },
            { type: 'eth-testnet', config: this.getNetworkConfigByType('eth-testnet') },
            { type: 'bsc-mainnet', config: this.getNetworkConfigByType('bsc-mainnet') },
            { type: 'bsc-testnet', config: this.getNetworkConfigByType('bsc-testnet') }
        ];
    }
}
